using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns the name of a bot in the given language. Can be called only if userTypeBot.can_be_edited == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetBotNameAsync(long botUserId = default, string languageCode = default)
    {

           using var activity =  StartCallActivity("GetBotNameAsync", typeof(GetBotName).FullName ?? "GetBotNameAsync");

           try
           {
             return client.GetBotNameAsync(botUserId, languageCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
